local function secret(def)for _,k in ipairs(def.keywords or{})do if k=="secret"then return true end end return false end
local function stone(id,name,text,count,next_id)local x={id=id,name=name,text=text,set="LOOTAPALOOZA",type="spell",class="hunter",collectible=false,rarity="rare",spell_school="nature",cost=5,on_play=function(ctx,self)for _=1,count do ctx:summon(ctx:controller(self),"LOOT_077t")end end};if next_id then x.triggers={{event="card_played",timing="after",active_zones={"hand"},condition=function(ctx,self,event)return event.player==ctx:controller(self)and secret(ctx:card_definition(ctx:entity(event.entity).card_id))end,effect=function(ctx,self)ctx:transform_preserving_scripts(self,next_id)end}}end;return x end
local card=stone("LOOT_080","Lesser Emerald Spellstone","Summon two 3/3 Wolves. <i>(Play a <b>Secret</b> to upgrade.)</i>",2,"LOOT_080t2");card.collectible=true;card.tokens={stone("LOOT_080t2","Emerald Spellstone","Summon three 3/3 Wolves. <i>(Play a <b>Secret</b> to upgrade.)</i>",3,"LOOT_080t3"),stone("LOOT_080t3","Greater Emerald Spellstone","Summon four 3/3 Wolves.",4,nil)};return card
